import React, { useState } from 'react';
import { 
    Box, 
    TextField, 
    Button, 
    Typography, 
    IconButton, 
    Divider, 
    Stack, 
    alpha,
    CircularProgress
} from '@mui/material';
import { 
    Add as AddIcon, 
    Delete as DeleteIcon, 
    Close as CloseIcon,
    CloudUpload as UploadIcon
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-hot-toast';
import { useSelector } from 'react-redux';
import FileUpload from '../../../components/FileUpload';

const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const INITIAL_GOAL_STATE = {
    title: '',
    description: '',
    plan_duration: '',
    goal_weight: '',
    image_url: ''
};

const AddGoals = () => {
    const navigate = useNavigate();
    const token = useSelector((state) => state.auth.token);
    const [goals, setGoals] = useState([INITIAL_GOAL_STATE]);
    const [isSaving, setIsSaving] = useState(false);

    const handleGoalChange = (index, field, value) => {
        setGoals(prev => {
            const newGoals = [...prev];
            newGoals[index] = { ...newGoals[index], [field]: value };
            return newGoals;
        });
    };

    const addGoalField = () => {
        setGoals(prev => [...prev, { ...INITIAL_GOAL_STATE }]);
        toast.success('New goal slot added!');
    };

    const removeGoalField = (index) => {
        if (goals.length > 1) {
            setGoals(prev => prev.filter((_, i) => i !== index));
        }
    };

    const handleSaveAll = async () => {
        if (!token) return;
        
        // Validation: backend only requires a title.
        const invalidGoals = goals.filter(g => !g.title || !g.title.trim());
        if (invalidGoals.length > 0) {
            toast.error('Please provide a Title for all goals');
            return;
        }

        setIsSaving(true);
        const toastId = toast.loading(`Saving ${goals.length} goals...`);

        try {
            // Sequential API calls or Parallel depending on preference.
            // Using Promise.all for speed.
            const savePromises = goals.map(goal => 
                fetch(`${BASE_URL}/goals`, {
                    method: 'POST',
                    headers: {
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(goal)
                }).then(res => res.json())
            );

            const results = await Promise.all(savePromises);
            
            const failures = results.filter(r => r.error);
            if (failures.length === 0) {
                toast.success('All goals added successfully!', { id: toastId });
                navigate('/goals');
            } else {
                toast.error(`${failures.length} goals failed to save.`, { id: toastId });
            }
        } catch (error) {
            console.error('Save error:', error);
            toast.error('Something went wrong during bulk save', { id: toastId });
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <Box sx={{ 
            minHeight: '100vh', 
            // bgcolor: '#001e08', 
            // color: '#FFF', 
            // p: { xs: 2.5, md: 5 },
            // pt: { xs: 2.5, md: 4 }
            m:2
        }}>
            
            {/* Header */}
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 4, px: 2  }}>
                <Typography variant="h5" sx={{ fontWeight: 900, fontSize: {xs: '1.5rem', md: '1.75rem'} }}>
                    Bulk Add Goals
                </Typography>
                <Stack direction="row" spacing={2}>
                    <Button
                        variant="contained"
                        color="secondary"
                        startIcon={<AddIcon />}
                        onClick={addGoalField}
                        sx={{ 
                            borderRadius: '12px', 
                            textTransform: 'none', 
                            fontWeight: 700,
                            bgcolor: '#9F6EDA',
                            '&:hover': { bgcolor: alpha('#9F6EDA', 0.8) }
                        }}
                    >
                        Add
                    </Button>
                    
                </Stack>
            </Box>

            {/* Content Area */}
            <Box sx={{ 
                bgcolor: alpha('#FFF', 0.02), 
                borderRadius: '24px', 
                bgcolor: '#001e08', 
                p: { xs: 2, md: 5 },
                border: '1px solid rgba(255,255,255,0.05)'
            }}>
                <Stack spacing={4}>
                    {goals.map((goal, index) => (
                        <Box 
                            key={index} 
                            sx={{ 
                                p: 3, 
                                borderRadius: '20px', 
                                bgcolor: alpha('#000', 0.2),
                                border: '1px solid rgba(255,255,255,0.03)',
                                position: 'relative'
                            }}
                        >
                            {goals.length > 1 && (
                                <IconButton 
                                    onClick={() => removeGoalField(index)}
                                    sx={{ 
                                        position: 'absolute', 
                                        top: 12, 
                                        right: 12, 
                                        color: '#FF5050',
                                        bgcolor: alpha('#FF5050', 0.1),
                                        '&:hover': { bgcolor: alpha('#FF5050', 0.2) }
                                    }}
                                    size="small"
                                >
                                    <DeleteIcon fontSize="small" />
                                </IconButton>
                            )}

                            <Typography variant="subtitle2" sx={{ color: '#4CC66E', fontWeight: 800, mb: 3, display: 'flex', alignItems: 'center', gap: 1 }}>
                                <Box sx={{ width: 24, height: 24, borderRadius: '6px', bgcolor: alpha('#4CC66E', 0.1), display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '12px' }}>
                                    {index + 1}
                                </Box>
                                GOAL DETAILS
                            </Typography>

                            <Box sx={{ display: 'flex', flexDirection: { xs: 'column', md: 'row' }, gap: 4 }}>
                                {/* Left: Title & Description */}
                                <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2.5 }}>
                                    <TextField
                                        fullWidth
                                        label="Goal Title"
                                        placeholder="e.g. Weight Loss"
                                        value={goal.title}
                                        onChange={(e) => handleGoalChange(index, 'title', e.target.value)}
                                        required
                                    />
                                    <TextField
                                        fullWidth
                                        multiline
                                        rows={4}
                                        label="Description"
                                        placeholder="Describe the goal objective..."
                                        value={goal.description}
                                        onChange={(e) => handleGoalChange(index, 'description', e.target.value)}
                                    />
                                    <Box sx={{ display: 'flex', flexDirection: { xs: 'column', sm: 'row' }, gap: 2.5 }}>
                                        <TextField
                                            fullWidth
                                            label="Plan Duration"
                                            placeholder="e.g. 12 weeks"
                                            value={goal.plan_duration}
                                            onChange={(e) => handleGoalChange(index, 'plan_duration', e.target.value)}
                                        />
                                        <TextField
                                            fullWidth
                                            type="number"
                                            label="Target Goal Weight (kg)"
                                            placeholder="e.g. 70"
                                            value={goal.goal_weight}
                                            onChange={(e) => handleGoalChange(index, 'goal_weight', e.target.value)}
                                            inputProps={{ min: 0, step: '0.1' }}
                                        />
                                    </Box>
                                </Box>

                                {/* Right: Image Upload */}
                                <Box sx={{ width: { xs: '100%', md: 320 } }}>
                                    <Typography variant="caption" sx={{ color: '#8B8D97', fontWeight: 700, mb: 1, display: 'block', textTransform: 'uppercase' }}>
                                        Goal Image
                                    </Typography>
                                    <FileUpload 
                                        folderName="goals"
                                        maxSizeMB={10}
                                        helperText="PNG, JPG or WEBP (max. 10MB)"
                                        existingImageUrl={goal.image_url}
                                        onUploadSuccess={(url) => handleGoalChange(index, 'image_url', url)}
                                        onRemove={() => handleGoalChange(index, 'image_url', '')}
                                    />
                                </Box>
                            </Box>
                        </Box>
                    ))}
                </Stack>

                {/* Bottom Actions */}
                <Box sx={{ 
                    display: 'flex', 
                    justifyContent: 'flex-end',
                    mt: 6, 
                    pt: 4, 
                    borderTop: '1px solid rgba(255,255,255,0.08)'
                }}>
                    <Button 
                        variant="contained" 
                        color="secondary"
                        onClick={handleSaveAll}
                        disabled={isSaving}
                        // sx={{ 
                        //     height: 52, 
                        //     minWidth: 200,
                        //     borderRadius: '14px',
                        //     textTransform: 'none',
                        //     fontWeight: 700,
                        //     fontSize: '1rem',
                        //     bgcolor: '#9F6EDA',
                        //     '&:hover': { bgcolor: alpha('#9F6EDA', 0.9) }
                        // }}
                    >
                        {isSaving ? <CircularProgress size={24} sx={{ color: '#FFF' }} /> : `Save ${goals.length} Goals`}
                    </Button>
                </Box>
            </Box>
        </Box>
    );
};

export default AddGoals;
